create extension if not exists pgcrypto;
create table tenants(id uuid primary key,name text not null,phone text not null);
create table users(id uuid primary key,tenant uuid not null references tenants(id) on delete cascade,name text not null,email text not null unique,hash text not null,role text not null check(role in ('admin','agent','viewer')),accounts jsonb not null default '[]');
create table sessions(id text primary key,"user" uuid not null references users(id) on delete cascade,expires bigint not null);
create index sessions_user_idx on sessions("user");
create table accounts(id uuid primary key,tenant uuid not null references tenants(id) on delete cascade,name text not null,channel text not null check(channel in ('instagram','messenger','whatsapp')),external text not null default '',secret text not null,mode text not null default 'demo' check(mode in ('demo','live')),bridge uuid);
create unique index accounts_external_idx on accounts(channel,external) where external<>'';
create index accounts_tenant_idx on accounts(tenant);
create table conversations(id uuid primary key,tenant uuid not null references tenants(id) on delete cascade,account uuid not null references accounts(id) on delete cascade,customer text not null,name text not null,status text not null check(status in ('open','resolved')),updated bigint not null,last_inbound bigint not null,unique(account,customer));
create index conversations_tenant_updated_idx on conversations(tenant,updated desc);
create table messages(id uuid primary key,conversation uuid not null references conversations(id) on delete cascade,direction text not null,body text not null,created bigint not null,state text not null,external text unique);
create index messages_conversation_created_idx on messages(conversation,created);
create table events(id text primary key,tenant text not null,payload jsonb not null,state text not null,error text not null default '',created bigint not null);
create table jobs(id uuid primary key,tenant uuid not null,account uuid not null,conversation uuid not null,message uuid,kind text not null,recipient text not null,body text not null,state text not null,error text not null default '',external text,created bigint not null);
create index jobs_tenant_created_idx on jobs(tenant,created desc);
create table audit(id uuid primary key,tenant uuid not null,action text not null,created bigint not null);
create index audit_tenant_created_idx on audit(tenant,created desc);
alter table tenants enable row level security;
alter table users enable row level security;
alter table sessions enable row level security;
alter table accounts enable row level security;
alter table conversations enable row level security;
alter table messages enable row level security;
alter table events enable row level security;
alter table jobs enable row level security;
alter table audit enable row level security;
